(function(){function init(){var form=document.querySelector('form.search-box[role="search"]');if(!form)return;var spacer=document.createElement("div");spacer.className="search-pin-spacer";spacer.setAttribute("aria-hidden","true");form.parentNode.insertBefore(spacer,form);var bars=[document.querySelector("header.site-header"),document.querySelector(".header-ticker")].filter(Boolean);var pinned=false;var queued=false;var GAP=8;function pinTop(){var bottom=0;bars.forEach(function(bar){var cs=getComputedStyle(bar);if(cs.position!=="sticky"||cs.display==="none")return;bottom=Math.max(bottom,bar.getBoundingClientRect().bottom)});return bottom+GAP}function setPinned(on,top){if(on===pinned){if(on)form.style.top=top+"px";return}pinned=on;spacer.style.height=on?form.offsetHeight+"px":"";form.style.top=on?top+"px":"";form.classList.toggle("is-pinned",on)}function update(){queued=false;var top=pinTop();setPinned(spacer.getBoundingClientRect().top<top,top)}function queue(){if(queued)return;queued=true;requestAnimationFrame(update)}window.addEventListener("scroll",queue,{passive:true});window.addEventListener("resize",queue);update()}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init()})();